import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"OmniRouter: domando el caos de modelos","description":"Por qué construí OmniRouter — la historia de convertir la rotación de modelos en un archivo de config, con balanceo y failover en un binario Go.","frontmatter":{"title":"OmniRouter: domando el caos de modelos","description":"Por qué construí OmniRouter — la historia de convertir la rotación de modelos en un archivo de config, con balanceo y failover en un binario Go."},"headers":[],"relativePath":"es/vibe-stories/story-2/index.md","filePath":"es/vibe-stories/story-2/index.md"}`),a={name:`es/vibe-stories/story-2/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="omnirouter-domando-el-caos-de-modelos" tabindex="-1">OmniRouter: domando el caos de modelos <a class="header-anchor" href="#omnirouter-domando-el-caos-de-modelos" aria-label="Permalink to “OmniRouter: domando el caos de modelos”">​</a></h1><p>El ecosistema de IA avanza a velocidad de scroll. El modelo que impulsó mi semana queda obsoleto el viernes, los precios giran, los tiers gratuitos aparecen y desaparecen. Mis apps se rompían por razones que no tenían nada que ver con mi código — así que convertí ese caos en problema de otro. Ese otro es <strong><a href="https://github.com/Godde3s/omnirouter" target="_blank" rel="noreferrer">OmniRouter</a></strong>.</p><h2 id="la-idea-clave" tabindex="-1">La idea clave <a class="header-anchor" href="#la-idea-clave" aria-label="Permalink to “La idea clave”">​</a></h2><p>El formato chat-completions de OpenAI ganó. Es la interfaz que todo cliente ya habla. OmniRouter presenta exactamente esa interfaz a tu app, y habla cualquier dialecto que cada upstream necesite del otro lado — GLM, Qwen, DeepSeek, endpoints propios. Tu código <strong>nunca</strong> cambia; el archivo de config cambia semanalmente.</p><h2 id="las-partes-dificiles" tabindex="-1">Las partes difíciles <a class="header-anchor" href="#las-partes-dificiles" aria-label="Permalink to “Las partes difíciles”">​</a></h2><ul><li><strong>Honestidad del streaming</strong> — retransmitir SSE token por token sin sorpresas de buffering exigió plomería cuidadosa.</li><li><strong>Detección de fallos</strong> — distinguir &quot;el modelo va lento&quot; de &quot;el modelo se está muriendo&quot; necesita ventanas de salud móviles, no sondeos de un tiro.</li><li><strong>Rotación justa</strong> — round-robin ponderado con cuotas, para gastar la capacidad barata antes que los tokens premium.</li></ul><p>OmniRouter junto a los <a href="/Usf/es/projects/glm-free-api/">puentes free-api</a> me da algo absurdo en papel y esencial en la práctica: un stack de IA multi-modelo con <strong>costo mensual cero</strong> y un archivo de config que manda sobre todos.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};